text:
1.2 Where bands come from: the Kronig–Penney model
The simplest periodic potential is a row of thin barriers of strength \(P\) spaced by \(a\). Bloch’s theorem then gives a single equation for the allowed energies:
\[
\cos(ka)=\cos(\alpha a)+P\,\frac{\sin(\alpha a)}{\alpha a},\qquad \alpha=\frac{\sqrt{2m_eE}}{\hbar}.
\]
The right-hand side can exceed 1 in magnitude, and then no real \(k\) exists: that energy is a gap. Increase \(P\) in the panel and watch the free-electron parabola break into bands, with gaps opening at \(ka=\pm\pi\) (the edge of the Brillouin zone).


Show the Python
viewof kp = Inputs.form({
  P: Inputs.range([0, 12], {value: 4, step: 0.1, label: "barrier strength P"}),
  a: Inputs.range([0.2, 1.0], {value: 0.5, step: 0.01, label: "lattice period a (nm)"})
})









Show the Python
kpOut = {
  const hbar = 1.054571817e-34, me = 9.1093837e-31, q = 1.602176634e-19, a = kp.a*1e-9;
  const E0 = hbar**2/(2*me*a*a)/q;              // eV, energy for alpha*a = 1
  const pts = [], free = [], bands = [];
  let inBand = false, start = 0;
  for (let i = 1; i &lt;= 6000; i++) {
    const x = 4*Math.PI*i/6000, E = E0*x*x;     // x = alpha*a
    const rhs = Math.cos(x) + kp.P*Math.sin(x)/x;
    if (Math.abs(rhs) &lt;= 1) {
      const ka = Math.acos(rhs);
      pts.push({k: ka/Math.PI, E}); pts.push({k: -ka/Math.PI, E});
      if (!inBand) { inBand = true; start = E; }
    } else if (inBand) { inBand = false; bands.push([start, E]); }
    let kf = x % (2*Math.PI); if (kf &gt; Math.PI) kf -= 2*Math.PI;
    free.push({k: kf/Math.PI, E});
  }
  if (inBand) bands.push([start, E0*16*Math.PI**2]);
  const gaps = bands.slice(1).map((b, i) =&gt; b[0] - bands[i][1]);
  return {pts, free, bands, gaps};
}
Plot.plot({
  width: Math.min(width, 1050), height: 420, x: {label: "ka/π (reduced zone)", domain: [-1, 1]},
  y: {label: "E (eV)", grid: true},
  marks: [
    Plot.dot(kpOut.free, {x: "k", y: "E", r: 0.6, fill: "#52514e", fillOpacity: 0.35}),
    Plot.dot(kpOut.pts, {x: "k", y: "E", r: 1.3, fill: "#2a78d6"}),
    Plot.tip(kpOut.pts, Plot.pointer({x: "k", y: "E", title: d =&gt; `ka/π = ${d.k.toFixed(3)}\nE = ${d.E.toFixed(2)} eV`}))
  ]
})


















Show the Python
html`&lt;div class="result-box"&gt;Blue: allowed states in the crystal. Grey: free-electron parabola folded into the first zone (P = 0).&lt;br&gt;
Band gaps: ${kpOut.gaps.slice(0, 3).map((g, i) =&gt; `E&lt;sub&gt;g${i+1}&lt;/sub&gt; = &lt;b&gt;${g.toFixed(2)} eV&lt;/b&gt;`).join(" · ")}&lt;/div&gt;`









Show the Python
a, P = 0.5e-9, 4.0
x = np.linspace(1e-4, 4*np.pi, 8000)               # alpha*a
E = (sl.hbar*x/a)**2/(2*sl.me)/sl.qe
rhs = np.cos(x) + P*np.sin(x)/x
ok = np.abs(rhs) &lt;= 1
ka = np.where(ok, np.arccos(np.clip(rhs, -1, 1)), np.nan)
band = np.floor(x/np.pi)                          # band index -&gt; extended-zone unfolding
k_ext = np.where(band % 2 == 0, ka + band*np.pi, (band + 1)*np.pi - ka)

fig, ax = plt.subplots(1, 2, figsize=(9, 4.2), sharey=True)
ax[0].plot(rhs, E); ax[0].axvspan(-1, 1, color=sl.PALETTE[0], alpha=0.08)
ax[0].set(xlabel="cos(αa) + P sin(αa)/(αa)", ylabel="E (eV)", xlim=(-3, 5))
ax[1].plot(k_ext/np.pi, E, label="crystal"); ax[1].plot(x/np.pi, E, ls="--", color=sl.INK2, lw=1.2, label="free electron")
for m in (1, 2, 3): ax[1].axvline(m, color=sl.GRID, lw=1)
ax[1].set(xlabel="ka/π (extended zone)"); ax[1].legend(fontsize=8)
plt.tight_layout(); plt.show()








Figure 1.1: Kronig–Penney model (a = 0.5 nm, P = 4). Left: the right-hand side of the dispersion relation; energies where it leaves the band [−1, 1] are forbidden. Right: the resulting E–k diagram in the extended zone, compared with a free electron.

2.2 Electrons and holes in the bands, live
Choose a material, a temperature and a Fermi-level position. The panel integrates \(g(E)f(E)\) numerically (no Boltzmann approximation) and compares the result with the formulas above. Move \(E_F\) inside a band to see the Boltzmann formula fail: that is a degenerate semiconductor (Section 2.6).


Show the Python
mats = ({
  Ge:   {Eg: 0.66, Nc: 1.04e19, Nv: 6.0e18},
  Si:   {Eg: 1.11, Nc: 2.8e19,  Nv: 1.2e19},
  InP:  {Eg: 1.35, Nc: 5.2e17,  Nv: 1.1e19},
  GaAs: {Eg: 1.42, Nc: 4.7e17,  Nv: 7.0e18}
})
viewof st = Inputs.form({
  mat: Inputs.select(Object.keys(mats), {value: "Si", label: "material"}),
  T: Inputs.range([50, 600], {value: 300, step: 5, label: "temperature T (K)"}),
  fe: Inputs.range([-0.15, 1.15], {value: 0.75, step: 0.005, label: "(E_F − E_v)/E_g"})
})


















Show the Python
stOut = {
  const m = mats[st.mat], kT = 8.617333e-5*st.T, Eg = m.Eg, EF = st.fe*Eg;
  const Nc = m.Nc*(st.T/300)**1.5, Nv = m.Nv*(st.T/300)**1.5;
  // DOS normalised so that the Boltzmann integral gives Nc: g = Nc * 2/sqrt(pi) * sqrt(x)/kT
  const f = (E) =&gt; 1/(1 + Math.exp((E - EF)/kT)), fh = (E) =&gt; 1/(1 + Math.exp((EF - E)/kT));  // fh = 1 − f without cancellation
  const cb = [], vb = []; let n = 0, p = 0; const dE = kT/200;
  for (let x = dE/2; x &lt; 40*kT + Math.max(0, EF - Eg) + Math.max(0, -EF); x += dE) {   // midpoint rule
    const gc = Nc*2/Math.sqrt(Math.PI)*Math.sqrt(x/kT)/kT, gv = Nv*2/Math.sqrt(Math.PI)*Math.sqrt(x/kT)/kT;
    const ne = gc*f(Eg + x), pe = gv*fh(-x);
    n += ne*dE; p += pe*dE;
    cb.push({E: Eg + x, d: ne}); vb.push({E: -x, d: pe});
  }
  const ni = Math.sqrt(Nc*Nv)*Math.exp(-Eg/(2*kT));
  const nB = Nc*Math.exp(-(Eg - EF)/kT), pB = Nv*Math.exp(-EF/kT);
  const EFi = Eg/2 - 0.5*kT*Math.log(Nc/Nv);
  const peak = Math.max(...cb.map(d =&gt; d.d), ...vb.map(d =&gt; d.d));
  return {cb: cb.filter(d =&gt; d.E &lt; Eg + 12*kT + Math.max(0, EF - Eg)), vb: vb.filter(d =&gt; d.E &gt; -12*kT - Math.max(0, -EF)),
          n, p, ni, nB, pB, EF, EFi, Eg, peak, kT};
}
Plot.plot({
  width: Math.min(width, 1050), height: 380,
  x: {label: "carriers per unit energy (cm⁻³ eV⁻¹, each band scaled to its own maximum)", domain: [0, 1.05]},
  y: {label: "E − E_v (eV)", grid: true},
  marks: [
    Plot.areaX(stOut.cb, {y: "E", x: d =&gt; d.d/Math.max(...stOut.cb.map(e =&gt; e.d)), fill: "#2a78d6", fillOpacity: 0.35}),
    Plot.lineX(stOut.cb, {y: "E", x: d =&gt; d.d/Math.max(...stOut.cb.map(e =&gt; e.d)), stroke: "#2a78d6", strokeWidth: 2}),
    Plot.areaX(stOut.vb, {y: "E", x: d =&gt; d.d/Math.max(...stOut.vb.map(e =&gt; e.d)), fill: "#eb6834", fillOpacity: 0.35}),
    Plot.lineX(stOut.vb, {y: "E", x: d =&gt; d.d/Math.max(...stOut.vb.map(e =&gt; e.d)), stroke: "#eb6834", strokeWidth: 2}),
    Plot.ruleY([0, stOut.Eg], {stroke: "#0b0b0b", strokeWidth: 1.5}),
    Plot.ruleY([stOut.EF], {stroke: "#4a3aa7", strokeWidth: 2, strokeDasharray: "6,4"}),
    Plot.ruleY([stOut.EFi], {stroke: "#52514e", strokeWidth: 1, strokeDasharray: "2,3"}),
    Plot.text([{y: stOut.EF, t: "E_F"}, {y: stOut.EFi, t: "E_Fi"}, {y: stOut.Eg, t: "E_c"}, {y: 0, t: "E_v"}],
              {x: 1.03, y: "y", text: "t", textAnchor: "end", dy: -6, fill: "#52514e"})
  ]
})


















