p = &lt;b&gt;${stOut.p.toExponential(2)}&lt;/b&gt; cm⁻³ (Boltzmann: ${stOut.pB.toExponential(2)})&lt;br&gt;
n&lt;sub&gt;i&lt;/sub&gt; = ${stOut.ni.toExponential(2)} cm⁻³ · np/n&lt;sub&gt;i&lt;/sub&gt;² = ${(stOut.n*stOut.p/stOut.ni**2).toFixed(3)} ·
E&lt;sub&gt;Fi&lt;/sub&gt; − E&lt;sub&gt;v&lt;/sub&gt; = ${stOut.EFi.toFixed(3)} eV · k&lt;sub&gt;B&lt;/sub&gt;T = ${(1000*stOut.kT).toFixed(1)} meV
${Math.min(stOut.Eg - stOut.EF, stOut.EF) &lt; 3*stOut.kT ? html`&lt;br&gt;&lt;b&gt;E&lt;sub&gt;F&lt;/sub&gt; is within 3k&lt;sub&gt;B&lt;/sub&gt;T of a band edge: degenerate, the Boltzmann formulas fail.&lt;/b&gt;` : ""}&lt;/div&gt;`

3.2 Doping explorer


Show the Python
matD = ({
  Si:   {Eg: 1.11, Nc: 2.8e19, Nv: 1.2e19, ni: 1.0e10, mue: 1450, muh: 490},
  Ge:   {Eg: 0.66, Nc: 1.04e19, Nv: 6.0e18, ni: 2.3e13, mue: 3900, muh: 1900},
  GaAs: {Eg: 1.42, Nc: 4.7e17, Nv: 7.0e18, ni: 2.1e6, mue: 8500, muh: 400}
})
viewof dp = Inputs.form({
  mat: Inputs.select(Object.keys(matD), {value: "Si", label: "material"}),
  lNd: Inputs.range([0, 20], {value: 16, step: 0.05, label: "log₁₀ N_d (cm⁻³), 0 = none"}),
  lNa: Inputs.range([0, 20], {value: 0, step: 0.05, label: "log₁₀ N_a (cm⁻³), 0 = none"}),
  T: Inputs.range([200, 700], {value: 300, step: 5, label: "temperature T (K)"})
})


















Show the Python
dpOut = {
  const m = matD[dp.mat], kT = 8.617333e-5*dp.T;
  const Nc = m.Nc*(dp.T/300)**1.5, Nv = m.Nv*(dp.T/300)**1.5;
  const ni = m.ni*(dp.T/300)**1.5*Math.exp(m.Eg/(2*0.025852) - m.Eg/(2*kT));   // Table 3.1 value at 300 K
  const Nd = dp.lNd &gt; 0 ? 10**dp.lNd : 0, Na = dp.lNa &gt; 0 ? 10**dp.lNa : 0, D = (Nd - Na)/2;
  const r = Math.sqrt(D*D + ni*ni), n = D &gt;= 0 ? D + r : ni*ni/(r - D), p = ni*ni/n;
  const EFi = m.Eg/2 - 0.5*kT*Math.log(Nc/Nv), EF = EFi + kT*Math.log(n/ni);
  const sigma = 1.602e-19*(n*m.mue + p*m.muh);       // S/cm (constant mobilities)
  const type = n &gt; 10*p ? "n-type" : p &gt; 10*n ? "p-type" : "nearly intrinsic";
  return {ni, n, p, EF, EFi, Eg: m.Eg, sigma, type, kT, deg: (m.Eg - EF &lt; 3*kT) || (EF &lt; 3*kT)};
}
Plot.plot({
  width: Math.min(width, 1050), height: 260, x: {domain: [0, 10], axis: null},
  y: {label: "E − E_v (eV)", domain: [-0.25, dpOut.Eg + 0.25], grid: true},
  marks: [
    Plot.rectY([{x1: 0, x2: 10, y1: dpOut.Eg, y2: dpOut.Eg + 0.25}], {x1: "x1", x2: "x2", y1: "y1", y2: "y2", fill: "#2a78d6", fillOpacity: 0.15}),
    Plot.rectY([{x1: 0, x2: 10, y1: -0.25, y2: 0}], {x1: "x1", x2: "x2", y1: "y1", y2: "y2", fill: "#eb6834", fillOpacity: 0.15}),
    Plot.ruleY([0, dpOut.Eg], {stroke: "#0b0b0b", strokeWidth: 2}),
    Plot.ruleY([dpOut.EFi], {stroke: "#52514e", strokeDasharray: "2,3"}),
    Plot.ruleY([dpOut.EF], {stroke: "#4a3aa7", strokeWidth: 2.5, strokeDasharray: "8,4"}),
    Plot.text([{y: dpOut.Eg, t: "E_c"}, {y: 0, t: "E_v"}, {y: dpOut.EFi, t: "E_Fi"}, {y: dpOut.EF, t: "E_F"}],
              {x: 9.9, y: "y", text: "t", textAnchor: "end", dy: -7, fill: "#0b0b0b"}),
    Plot.text([{y: dpOut.Eg + 0.12, t: "conduction band"}, {y: -0.12, t: "valence band"}], {x: 0.2, y: "y", text: "t", textAnchor: "start", fill: "#52514e"})
  ]
})


















